dataModel:
public enum StartKind { Road, Hub, Crash }
public sealed record ModeDef(string Id, StartKind Start, bool Ironman,
  bool KeepPlaying, IReadOnlyDictionary<string,float> Dials);
public sealed class WorldConfig {
  public string ModeId = "normal";
  public Dictionary<string,float> Dials = new();
  public CustomCounts? Custom;
  public float Get(string key) => Dials.TryGetValue(key, out var v) ? v : 1f;
}

public enum Era { Early, Mid, Late }
public enum Ending { HiveVictory, Coalition, Reunited, Defeat }
public sealed record EraDef(Era Era, int FromYear, float HordeGrowth, float RaidGrowth);
public sealed record ForecastCause(string SourceId, float Severity, int Day, string Text);
public sealed record Forecast(float Level, IReadOnlyList<ForecastCause> Causes);
public sealed class CampaignState { public int OutbreakEndsYear; public Ending? Ended; public bool KeptPlaying; }

public sealed record DiaryEntry(byte Hour, LogKind Kind, string Text);
public sealed class Diary { public List<List<DiaryEntry>> Days = new(); }
public sealed record HistoryRow(int Day, float[] Values); // columns by schema index
public sealed record AchievementDef(string Id, string Title, string IconKey, string Condition);
public sealed record HallEntry(int Version, string Campaign, Ending Ending, int Days, int PeakPeople, string[] Founders);
public sealed record ChronicleFrame(int Day, bool Key, Dictionary<int,int> TileOwnerDelta);

public sealed record CodexEntry(string Id, string Category, string Title, string BodyTemplate, string UnlockOn);
public sealed record GuideStep(string Id, int Phase, string Text, string Why, string Condition, string? ShowMeTarget);
public enum CauseKind { Starvation, Wounds, Illness, Horde, Raid, Desertion }
public sealed record CauseFactor(string Text, int? Day);
public sealed record WhyChain(CauseKind Kind, string Headline, IReadOnlyList<CauseFactor> Factors);

public enum WatchKind { Person, Team, Horde, Group, Base }
public sealed record WatchEntry(WatchKind Kind, int Id, string NameWhenPinned, HexCoord? LastSeen, int? LastSize);
public sealed record MapNote(int Id, HexCoord Tile, string IconId, string Text);
public sealed record SearchHit(string Label, string Kind, string TargetId, float Score);

public sealed record RunConfig(string Mode, string Size, int SeedFrom, int SeedTo, int Days, string Style);
public sealed record RunReport(int Seed, int DaysPlayed, Ending? Ending, int Deaths,
  Dictionary<string,int> DeathsByCause, float CardsPerDay, int PeakPeople);
public interface IMetricCollector { void OnEvent(IDomainEvent e, World w); void OnDay(World w); }

public sealed class TickProfiler {
  readonly Dictionary<string, List<double>> _ms = new();
  public IDisposable Measure(string stage) => new Scope(this, stage, Stopwatch.GetTimestamp());
}
public sealed record PerfBudget(string Size, double HourMs, double MidnightMs, double EnemyTurnMs);
public readonly record struct MapChunk(int Cx, int Cy, int Version);

public enum ArtKind { Sprite, SpriteSheet, Model3D, Icon }
public sealed record ArtSpec(string Key, ArtKind Kind, int W, int H,
  float PivotX, float PivotY, int Frames, int Facings, string Status);
// file convention: art/<category>/<name>.png  <=>  key "<category>.<name>"

public sealed record TerrainArt(string TerrainId, string Season, string BaseKey, string[] VariantKeys);
public readonly record struct TileVisual(byte Terrain, byte Season, byte Wetness, byte Snow, bool Live);
// variant index = Hash(q, r) % VariantKeys.Length  (stable, not the sim Rng)

public enum UnitAnim { Idle, Walk, Run, Shoot, Melee, Reload, Hit, Downed, Die }
public sealed record AnimDef(UnitAnim Anim, int Frames, float Fps, bool Loop, int[] EventFrames);
public sealed record LookLayers(string Body, string Skin, string Hair, string Top, string Pants, string? Weapon);

public sealed record PropArt(string Key, int CellsW, int CellsH, int Rotations, string[] StateKeys);
// state keys e.g. "closed","open","searched","broken"
public readonly record struct PropVisual(int DefId, byte Rotation, byte State, float BuiltPct);

public sealed record UiToken(string Name, string Value); // "color.danger" = "#c8463c"
public sealed record IconSpec(string Key, int[] Sizes, bool Svg);
// screens reference tokens and icon keys only, never literal colours

public enum MusicState { Title, Day, Night, Tension, Crisis, Festival, BattleQuiet, BattleSeen, BattleFight, BattleWin, BattleLose }
public sealed record Situation(bool InBattle, bool EnemySeen, bool Fighting, float Threat, bool Night);
public sealed record CueDef(string Id, string[] Clips, string Bus, float PitchVar, float Cooldown);
public interface IMusicDirector { (MusicState state, string[] stings) Direct(Situation s, double now); }

public sealed record BuildInfo(string Version, string Commit, DateTime BuiltUtc, string Platform);
public sealed record CrashReport(BuildInfo Build, string Exception, string StackTrace,
  string LastLogLines, string? CrashSavePath, string ModeId, int Day);
